#!/usr/bin/env python3
"""The judge: decide whether one input faults a staged build of the library.

`crash`   the sanitizer reported a memory error.
`clean`   the parser ran the input to completion inside the build's own limits.
`abort`   the process died without a sanitizer report (a libFuzzer
          out-of-memory, an assertion, another deadly signal). That is not
          evidence of a memory error and is never scored as a repair either.
`timeout` the run did not finish, which is neither of the above.

`--target` may name one fuzz entry point or a staged directory. Given a
directory, the judge picks the parser the input is written for from its
container magic, so one command replays IPC stream, IPC file and Parquet input.

The verdict record carries the sanitizer's bug label, the innermost frame and
the source locations of the faulting stack, so a graded run and a run the agent
performed by hand cannot disagree about what happened.
"""
import argparse
import json
import os
import re
import subprocess
import sys

SAN_ERROR = re.compile(
    r"ERROR:\s*(?:Address|Leak|Memory|Thread|UndefinedBehavior)Sanitizer:\s*"
    r"([A-Za-z0-9_-]+)")
# Not anchored to the start of the line, so a runner that prefixes each line
# with a timestamp or a stream tag cannot hide the frames.
FRAME = re.compile(
    r"#(\d+)\s+0x[0-9a-f]+\s+in\s+(.+?)\s+(/src/arrow/(\S+?)):(\d+)")
ABORT = re.compile(r"ERROR: libFuzzer: (deadly signal|out-of-memory|timeout)")
DEFAULT_TIMEOUT = 120
PARSERS = {"parquet": "parquet-arrow-fuzz", "file": "arrow-ipc-file-fuzz",
           "stream": "arrow-ipc-stream-fuzz"}


def container_kind(input_path):
    """Which parser an input is written for, read from its magic bytes."""
    with open(input_path, "rb") as fh:
        data = fh.read()
    if data[:4] == b"PAR1" or data[-4:] == b"PAR1":
        return "parquet"
    if data[:6] == b"ARROW1" or data[-6:] == b"ARROW1":
        return "file"
    return "stream"


def resolve_target(target, input_path):
    if os.path.isdir(target):
        return os.path.join(target, PARSERS[container_kind(input_path)])
    return target


def validate(target, input_path, timeout=DEFAULT_TIMEOUT):
    """Run one input through `target` and classify what came back."""
    target = resolve_target(target, input_path)
    env = dict(os.environ)
    # Leak accounting and allocator behaviour only; nothing here changes
    # whether a memory error is reported or what exit code it produces.
    env["ASAN_OPTIONS"] = "detect_leaks=0:allocator_may_return_null=1:symbolize=1"
    try:
        proc = subprocess.run([target, "-runs=1", "-rss_limit_mb=2560", input_path],
                              capture_output=True, text=True, errors="replace",
                              timeout=timeout, env=env)
        output = (proc.stdout or "") + (proc.stderr or "")
        exit_code, timed_out = proc.returncode, False
    except subprocess.TimeoutExpired as expired:
        output = "".join(
            stream.decode("utf-8", "replace") if isinstance(stream, bytes)
            else (stream or "")
            for stream in (expired.stdout, expired.stderr))
        exit_code, timed_out = None, True
    except OSError as err:
        return {"verdict": "error", "bug_type": None, "crash_function": None,
                "frames": [], "exit_code": None, "target": target,
                "input": input_path, "detail": str(err)}

    error = SAN_ERROR.search(output)
    aborted = ABORT.search(output)
    frames, function = [], None
    if error:
        for match in FRAME.finditer(output[error.end():]):
            if int(match.group(1)) == 0 and frames:
                break
            if function is None:
                s = re.sub(r"\(anonymous namespace\)::", "", match.group(2))
                while "<" in s and ">" in s:
                    s2 = re.sub(r"<[^<>]*>", "", s)
                    if s2 == s:
                        break
                    s = s2
                s = s.split("(")[0].strip()
                quals = re.findall(r"[A-Za-z_~]\w*(?:::[A-Za-z_~]\w*)+", s)
                function = quals[-1] if quals else (s.split()[-1] if s else match.group(2))
            frames.append("%s:%s" % (match.group(4), match.group(5)))
    if timed_out:
        verdict = "timeout"
    elif error:
        verdict = "crash"
    elif aborted:
        verdict = "abort"
    else:
        verdict = "clean"
    return {
        "verdict": verdict,
        "bug_type": error.group(1) if error else (aborted.group(1) if aborted else None),
        "crash_function": function,
        "frames": frames[:12],
        "exit_code": exit_code,
        "target": target,
        "input": input_path,
    }


def main():
    parser = argparse.ArgumentParser(
        description="Run one input against a staged build and report a verdict")
    parser.add_argument("--target", required=True,
                        help="staged directory or one fuzz entry point")
    parser.add_argument("--input", required=True, help="path to the input file")
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT,
                        help="seconds before the run is called a timeout")
    parser.add_argument("--expect", choices=["crash", "clean", "abort", "timeout"],
                        help="exit non-zero unless the verdict matches")
    parser.add_argument("--quiet", action="store_true")
    args = parser.parse_args()

    result = validate(args.target, args.input, args.timeout)
    print(result["verdict"] if args.quiet else json.dumps(result, indent=2))
    if args.expect:
        sys.exit(0 if result["verdict"] == args.expect else 1)




